PRAGMA foreign_keys=ON;
CREATE TABLE Drivers(Id INTEGER PRIMARY KEY,FullName TEXT NOT NULL,LicenseNumber TEXT NOT NULL UNIQUE,LicenseExpiresOn TEXT NOT NULL,Active INTEGER NOT NULL);
CREATE TABLE Vehicles(Id INTEGER PRIMARY KEY,PlateNumber TEXT NOT NULL UNIQUE,MakeModel TEXT NOT NULL,Year INTEGER NOT NULL,Odometer INTEGER NOT NULL,Status TEXT NOT NULL,CreatedAt TEXT NOT NULL);
CREATE TABLE Users(Id INTEGER PRIMARY KEY,Username TEXT NOT NULL UNIQUE,PasswordHash TEXT NOT NULL,Role TEXT NOT NULL,DriverId INTEGER UNIQUE REFERENCES Drivers(Id),CreatedAt TEXT NOT NULL);
CREATE TABLE Assignments(Id INTEGER PRIMARY KEY,VehicleId INTEGER NOT NULL REFERENCES Vehicles(Id),DriverId INTEGER NOT NULL REFERENCES Drivers(Id),StartsAt TEXT NOT NULL,EndsAt TEXT,Purpose TEXT NOT NULL,CreatedById INTEGER NOT NULL REFERENCES Users(Id),CreatedAt TEXT NOT NULL);
CREATE TABLE MaintenanceRecords(Id INTEGER PRIMARY KEY,VehicleId INTEGER NOT NULL REFERENCES Vehicles(Id),ServiceType TEXT NOT NULL,Odometer INTEGER NOT NULL,Cost TEXT NOT NULL,ServicedOn TEXT NOT NULL,Notes TEXT NOT NULL);
